include { STRINGTIE_STRINGTIE } from 'nf-core/stringtie/stringtie'
include { STRINGTIE_MERGE     } from 'nf-core/stringtie/merge'


workflow BAM_STRINGTIE_MERGE {
    take:
    ch_bams    // channel: [ meta, srbam, lrbam ]
    ch_mode    // channel: [ val(mode) ]
    ch_chrgtf  // channel: [ meta, gtf ]

    main:

    STRINGTIE_STRINGTIE(
        ch_bams,
        ch_mode,
        ch_chrgtf.map { _meta, gtf -> [gtf] }
    )

    STRINGTIE_STRINGTIE.out.transcript_gtf
        .map { _meta, gtf -> gtf }
        .toSortedList { a, b -> a.name <=> b.name }
        .filter { gtfs -> gtfs.size() > 0 }
        .map { gtfs -> [ [id: 'stringtie_merge'], gtfs ] }
        .set { collected_gtfs }

    STRINGTIE_MERGE(
        collected_gtfs,
        ch_chrgtf
    )

    emit:
    stringtie_gtf = STRINGTIE_MERGE.out.merged_gtf // channel: [ meta, gtf ]
}

nextflow_workflow {

    name "Test BAM_STRINGTIE_MERGE"
    script "../main.nf"
    workflow "BAM_STRINGTIE_MERGE"
    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "stringtie"
    tag "stringtie/stringtie"
    tag "stringtie/merge"
    tag "subworkflows/bam_stringtie_merge"

    test("Should merge transcripts across multiple samples") {

        when {
            workflow {
                """
                input[0] = Channel.of([
                                [ id:'sample1', strandedness:'reverse' ],
                                file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/bam/test.paired_end.sorted.bam", checkIfExists: true),
                                file(params.modules_testdata_base_path + "genomics/homo_sapiens/pacbio/bam/test.sorted.bam", checkIfExists: true)
                            ])
                input[1] = Channel.value("mix-reads-assembly")
                input[2] = Channel.of([
                                [ id:'annotation' ],
                                file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genome.gtf", checkIfExists: true)
                            ])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(sanitizeOutput(workflow.out)).match() },
            )
        }
    }

    test("Should skip merge when no BAM files are provided") {
        tag "empty_input"

        when {
            workflow {
                """
                input[0] = Channel.empty()
                input[1] = Channel.value("mix-reads-assembly")
                input[2] = Channel.of([
                                [ id:'annotation' ],
                                file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genome.gtf", checkIfExists: true)
                            ])
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert workflow.out.stringtie_gtf.size() == 0 },
            )
        }
    }

}
